-- GommaRush baseline part 3/3: constraints, indexes, triggers, RLS, comments.
-- Parts 1 and 2 must be applied first (valid_client_offer_request_tyres
-- depends on is_valid_tyre_request()).
set search_path = "$user", public, extensions;

