alter table public.vehicles add constraint vehicles_color_key_chk CHECK (((color_key IS NULL) OR (color_key = ANY (ARRAY['blue'::text, 'purple'::text, 'teal'::text, 'indigo'::text, 'slate'::text, 'cyan'::text, 'rose'::text, 'amber'::text]))));
