-- ============================= INDEXES ===============================
create index if not exists catalogue_conflicts_open_idx ON public.catalogue_conflicts USING btree (status, created_at DESC);
create index if not exists catalogue_conflicts_run_idx ON public.catalogue_conflicts USING btree (import_run_id);
create index if not exists catalogue_import_rows_run_action_idx ON public.catalogue_import_rows USING btree (import_run_id, action);
create unique index if not exists catalogue_import_rows_run_row_uidx ON public.catalogue_import_rows USING btree (import_run_id, source_row);
create index if not exists catalogue_import_rows_run_validation_idx ON public.catalogue_import_rows USING btree (import_run_id, validation_result);
create unique index if not exists catalogue_import_runs_checksum_uidx ON public.catalogue_import_runs USING btree (supplier_id, adapter, file_checksum) WHERE (status = 'committed'::text);
create index if not exists catalogue_import_runs_recent_idx ON public.catalogue_import_runs USING btree (created_at DESC);
create index if not exists catalogue_import_runs_status_idx ON public.catalogue_import_runs USING btree (status);
create index if not exists catalogue_products_brand_idx ON public.catalogue_products USING btree (brand);
create index if not exists catalogue_products_ean_idx ON public.catalogue_products USING btree (ean) WHERE (ean IS NOT NULL);
create index if not exists catalogue_products_last_seen_idx ON public.catalogue_products USING btree (last_seen_at DESC);
create index if not exists catalogue_products_mfr_code_idx ON public.catalogue_products USING btree (manufacturer_product_code) WHERE (manufacturer_product_code IS NOT NULL);
create index if not exists catalogue_products_review_idx ON public.catalogue_products USING btree (review_required) WHERE (review_required = true);
create index if not exists catalogue_products_size_idx ON public.catalogue_products USING btree (width_mm, aspect_ratio, rim_inch, season);
create unique index if not exists catalogue_products_validated_ean_uidx ON public.catalogue_products USING btree (ean) WHERE ((ean IS NOT NULL) AND (ean_status = ANY (ARRAY['valid'::text, 'recovered_leading_zero'::text])));
create index if not exists client_offer_requests_company_name_idx ON public.client_offer_requests USING btree (company_name);
