-- ============================= COMMENTS ==============================
comment on table public.catalogue_conflicts is 'Cases the importer deliberately refused to resolve. Nothing here is ever settled by picking an arbitrary value - a human decides, or it stays open.';
comment on table public.catalogue_import_rows is 'Staging + audit for every source row of an import. raw_payload is the untouched source and is never overwritten.';
comment on table public.catalogue_import_runs is 'One uploaded supplier catalogue file. status = ''committed'' is the ONLY state that means the data landed; anything else is in flight or failed.';
comment on table public.catalogue_products is 'One normalised tyre SKU. Canonical specifications only - no supplier price, no stock, no physical unit. Never deleted because a supplier file stopped listing it.';
comment on table public.product_identifiers is 'Every code that resolves to a catalogue product - EAN/GTIN, manufacturer code, supplier article code. The warehouse barcode scanner queries normalized_value here.';
comment on table public.quote_request_reference_counter is 'Per-day counter backing quote_requests.public_reference (GR-YYMMDD-NNNN). One row per calendar day, Europe/Rome.';
comment on table public.supplier_listing_prices is 'Supplier purchase price and stock, one row per observation. SUPPLIER COST DATA - must never be reachable from a customer-facing query. Separated from catalogue_products so a price refresh cannot rewrite specifications and a product query cannot leak a cost.';
comment on table public.supplier_product_listings is 'One supplier''s listing of one catalogue product. Two listings may share a product (new stock vs old DOT). Marked inactive only after a COMPLETE catalogue snapshot omits it - never after a partial file.';
comment on column public.catalogue_import_runs.import_mode is 'complete = the supplier''s whole catalogue (may propose deactivations); partial / manual_correction = must never deactivate anything.';
comment on column public.catalogue_products.scan_ready is 'True only when the EAN passed GS1 check-digit validation and may be trusted for warehouse barcode matching.';
comment on column public.catalogue_products.weight_category is 'Supplier weight bucket as shipped (ISB ''1''..''4''). NOT kilograms - see weight_kg.';
comment on column public.inventory_scans.stand_code is 'DEPRECATED: stand/stativ allocation was removed from the active product. Historical value only — no active application code reads or writes this column.';
comment on column public.inventory_units.last_stand_code is 'DEPRECATED: stand/stativ allocation was removed from the active product. Historical value only — no active application code reads or writes this column.';
comment on column public.orders.stand_code is 'DEPRECATED: stand/stativ allocation was removed from the active product. Historical value only — no active application code reads or writes this column.';
comment on column public.quote_requests.delivery_preference is 'Fastest delivery requested across the items (''48h'' or ''7d''), denormalised at insert time so the admin list can show and filter on it without joining items.';
comment on column public.quote_requests.notes is 'Optional free-text note from the customer ("Note aggiuntive"). Never interpreted, only displayed and exported.';
comment on column public.quote_requests.notification_email_sent is 'LEGACY (superseded 2026-08-27) by notification_status. Kept in sync by the application so nothing that still reads it breaks.';
comment on column public.quote_requests.request_number is 'LEGACY (superseded 2026-08-27) by public_reference. Retained so existing rows and any external reference to GR-1000-style numbers still resolve. Not shown in the UI.';
